var MatrixSuprema2025A1B2C3D4E5F6;
(function (powerbi) {
    "use strict";

    var visuals;
    (function (visuals) {
        var plugins;
        (function (plugins) {

            class Visual {
                constructor(options) {
                    this.target = options.element;
                    this.host = options.host;

                    // DEBUG: Forzar estilos extremos en el target
                    this.target.style.cssText = 
                        'width: 100% !important; ' +
                        'height: 100% !important; ' +
                        'background: red !important; ' +
                        'border: 10px solid blue !important; ' +
                        'position: relative !important; ' +
                        'overflow: visible !important; ' +
                        'display: block !important;';

                    // Crear contenedor hijo con colores extremos
                    this.container = document.createElement('div');
                    this.container.style.cssText = 
                        'width: 100%; ' +
                        'height: 100%; ' +
                        'background: yellow !important; ' +
                        'border: 5px solid green !important; ' +
                        'position: absolute; ' +
                        'top: 0; ' +
                        'left: 0; ' +
                        'z-index: 9999; ' +
                        'display: block; ' +
                        'overflow: visible;';

                    // Texto gigante
                    this.container.innerHTML = 
                        '<div style="' +
                        'background: black; ' +
                        'color: white; ' +
                        'font-size: 48px; ' +
                        'font-weight: bold; ' +
                        'padding: 50px; ' +
                        'margin: 20px; ' +
                        'border: 10px solid red; ' +
                        'text-align: center; ' +
                        'position: relative; ' +
                        'z-index: 10000;' +
                        '">' +
                        '🔴 VISUAL CARGADA 🔴<br>' +
                        'TIMESTAMP: ' + Date.now() + '<br>' +
                        'TARGET: ' + (this.target ? 'OK' : 'NULL') + '<br>' +
                        'HOST: ' + (this.host ? 'OK' : 'NULL') +
                        '</div>';

                    this.target.appendChild(this.container);
                }

                update(options) {
                    if (!this.container) return;

                    var html = '<div style="' +
                        'background: purple; ' +
                        'color: yellow; ' +
                        'font-size: 36px; ' +
                        'font-weight: bold; ' +
                        'padding: 30px; ' +
                        'border: 8px solid orange;' +
                        '">';

                    html += '⚡ UPDATE LLAMADO ⚡<br>';
                    html += 'Timestamp: ' + Date.now() + '<br>';

                    if (!options) {
                        html += 'OPTIONS: NULL<br>';
                    } else {
                        html += 'OPTIONS: OK<br>';
                        html += 'DATAVIEWS: ' + (options.dataViews ? options.dataViews.length : 'NULL') + '<br>';

                        if (options.dataViews && options.dataViews[0]) {
                            html += 'MATRIX: ' + (options.dataViews[0].matrix ? 'OK' : 'NULL') + '<br>';

                            if (options.dataViews[0].matrix) {
                                var matrix = options.dataViews[0].matrix;
                                html += 'ROWS: ' + (matrix.rows && matrix.rows.root ? 'OK' : 'NULL') + '<br>';
                                html += 'COLS: ' + (matrix.columns && matrix.columns.root ? 'OK' : 'NULL') + '<br>';
                            }
                        }
                    }

                    html += '</div>';
                    this.container.innerHTML = html;
                }

                enumerateObjectInstances(options) {
                    return [];
                }

                destroy() {
                    if (this.container) {
                        this.container.innerHTML = '';
                    }
                }
            }

            plugins.MatrixSuprema2025A1B2C3D4E5F6 = {
                name: 'MatrixSuprema2025A1B2C3D4E5F6',
                displayName: 'Matrix Suprema DEBUG',
                class: 'Visual',
                apiVersion: '5.1.0',
                create: function (options) {
                    return new Visual(options);
                },
                custom: true
            };

        })(plugins = visuals.plugins || (visuals.plugins = {}));
    })(visuals = powerbi.visuals || (powerbi.visuals = {}));
})(window['powerbi'] || (window['powerbi'] = {}));

MatrixSuprema2025A1B2C3D4E5F6 = window['powerbi'].visuals.plugins.MatrixSuprema2025A1B2C3D4E5F6;

